-- Imports the approved fictional Hope database dataset into the shared Production scope.
-- The source dump credits Jeremias C. Esperanza (NEU CCS) and includes destructive DROP statements; only its data rows are mapped here.
-- Source audit trigger code is not imported; this migration records one summary event in the ERP audit log.

create table public.erp_payments (
  access_scope text not null check (access_scope in ('sandbox', 'production')),
  or_no text not null check (length(pg_catalog.btrim(or_no)) > 0),
  pay_date date not null,
  amount numeric(12, 2) not null check (amount >= 0),
  trans_no text not null,
  is_deleted boolean not null default false,
  stamp text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (access_scope, or_no),
  foreign key (access_scope, trans_no)
    references public.erp_sales (access_scope, trans_no)
    on update cascade on delete restrict
);

create unique index erp_payments_scope_or_no_ci_idx
  on public.erp_payments (access_scope, pg_catalog.lower(or_no));
create index erp_payments_scope_trans_date_idx
  on public.erp_payments (access_scope, trans_no, pay_date desc)
  where not is_deleted;

create trigger erp_payments_enforce_write
  before insert or update on public.erp_payments
  for each row execute function public.enforce_hr_sales_write(
    'sales.add', 'sales.edit', 'sales.delete', 'or_no', 'pay_date,amount,trans_no'
  );

alter table public.erp_payments enable row level security;
create policy "Scoped users can read payments"
  on public.erp_payments for select to authenticated
  using ((select public.has_erp_permission(access_scope, 'sales.view')));
create policy "Scoped users can add payments"
  on public.erp_payments for insert to authenticated
  with check ((select public.has_erp_permission(access_scope, 'sales.add')));
create policy "Scoped users can update payments"
  on public.erp_payments for update to authenticated
  using ((select public.has_erp_permission(access_scope, 'sales.edit')) or (select public.has_erp_permission(access_scope, 'sales.delete')))
  with check ((select public.has_erp_permission(access_scope, 'sales.edit')) or (select public.has_erp_permission(access_scope, 'sales.delete')));
revoke all on public.erp_payments from anon, authenticated;
grant select, insert, update on public.erp_payments to authenticated;
grant all on public.erp_payments to service_role;

do $production_import$
begin
  if exists (select 1 from public.erp_customers where access_scope = 'production')
    or exists (select 1 from public.erp_products where access_scope = 'production')
    or exists (select 1 from public.erp_product_prices where access_scope = 'production')
    or exists (select 1 from public.erp_employees where access_scope = 'production')
    or exists (select 1 from public.erp_jobs where access_scope = 'production')
    or exists (select 1 from public.erp_departments where access_scope = 'production')
    or exists (select 1 from public.erp_job_histories where access_scope = 'production')
    or exists (select 1 from public.erp_sales where access_scope = 'production')
    or exists (select 1 from public.erp_sales_details where access_scope = 'production')
    or exists (select 1 from public.erp_payments where access_scope = 'production') then
    raise exception 'Production ERP data already exists; inspect it and plan a conflict-safe import before applying this migration.';
  end if;

  alter table public.erp_customers disable trigger erp_customers_enforce_write;
  alter table public.erp_products disable trigger erp_products_enforce_write;
  alter table public.erp_product_prices disable trigger erp_product_prices_enforce_write;
  alter table public.erp_employees disable trigger erp_employees_enforce_write;
  alter table public.erp_jobs disable trigger erp_jobs_enforce_write;
  alter table public.erp_departments disable trigger erp_departments_enforce_write;
  alter table public.erp_job_histories disable trigger erp_job_histories_enforce_write;
  alter table public.erp_sales disable trigger erp_sales_enforce_write;
  alter table public.erp_sales_details disable trigger erp_sales_details_enforce_write;
  alter table public.erp_payments disable trigger erp_payments_enforce_write;


  if (select count(*) from public.erp_departments where access_scope = 'production') <> 8
    or (select count(*) from public.erp_jobs where access_scope = 'production') <> 14
    or (select count(*) from public.erp_employees where access_scope = 'production') <> 32
    or (select count(*) from public.erp_customers where access_scope = 'production') <> 82
    or (select count(*) from public.erp_products where access_scope = 'production') <> 57
    or (select count(*) from public.erp_product_prices where access_scope = 'production') <> 79
    or (select count(*) from public.erp_job_histories where access_scope = 'production') <> 54
    or (select count(*) from public.erp_sales where access_scope = 'production') <> 124
    or (select count(*) from public.erp_sales_details where access_scope = 'production') <> 313
    or (select count(*) from public.erp_payments where access_scope = 'production') <> 165 then
    raise exception 'Production seed row counts did not match the reviewed dataset.';
  end if;

  alter table public.erp_customers enable trigger erp_customers_enforce_write;
  alter table public.erp_products enable trigger erp_products_enforce_write;
  alter table public.erp_product_prices enable trigger erp_product_prices_enforce_write;
  alter table public.erp_employees enable trigger erp_employees_enforce_write;
  alter table public.erp_jobs enable trigger erp_jobs_enforce_write;
  alter table public.erp_departments enable trigger erp_departments_enforce_write;
  alter table public.erp_job_histories enable trigger erp_job_histories_enforce_write;
  alter table public.erp_sales enable trigger erp_sales_enforce_write;
  alter table public.erp_sales_details enable trigger erp_sales_details_enforce_write;
  alter table public.erp_payments enable trigger erp_payments_enforce_write;

  values (null, 'DATA_IMPORT', 'production_seed', 'HopeDB_audit.sql.txt', jsonb_build_object(
    'erp_customers', 82,
    'erp_departments', 8,
    'erp_employees', 32,
    'erp_job_histories', 54,
    'erp_jobs', 14,
    'erp_payments', 165,
    'erp_product_prices', 79,
    'erp_products', 57,
    'erp_sales', 124,
    'erp_sales_details', 313,
    'source', 'User-approved fictional Hope database seed'
  ));
end;
$production_import$;
